<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{Http,Mail,Queue,DB};
use App\Models\User;
class MarketingEmailDeliveryTest extends TestCase {
 use RefreshDatabase;
 private function fixture():array {Http::preventStrayRequests();Queue::fake();Mail::fake();$this->actingAs(User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]));config(['marketing.execution_enabled'=>false,'marketing.email_test_enabled'=>true,'mail.default'=>'smtp','mail.from.address'=>'sender@example.test']);$t=app(\App\Services\Marketing\MarketingContentTemplates::class)->save(auth()->id(),['version'=>0,'channel'=>'email','name'=>'Test','language'=>'en','body'=>'A test','subject'=>'Campaign test','format'=>'image']);$c=app(\App\Services\Marketing\MarketingCampaigns::class)->saveChannelDraft(auth()->id(),['version'=>0,'channel'=>'email','name'=>'Email conversion test','document'=>['template_id'=>$t['id']]],null);return $c;}
 public function test_one_recipient_is_queued_once_and_uses_email_tracking(){ $c=$this->fixture();$p=['version'=>$c['version'],'recipient'=>'owner@example.test','landing_url'=>url('/'),'confirmed'=>true];$r=$this->postJson('/admin/marketing/campaigns/'.$c['id'].'/email-test',$p)->assertCreated();$id=$r->json('delivery.id');$this->postJson('/admin/marketing/campaigns/'.$c['id'].'/email-test',$p)->assertOk()->assertJsonPath('delivery.id',$id);$this->assertDatabaseCount('marketing_email_deliveries',1);$this->assertDatabaseHas('marketing_tracking_links',['channel'=>'email','post_id'=>null,'campaign_id'=>$c['id']]);Mail::assertNothingSent();Http::assertNothingSent(); }
 public function test_worker_accepts_once_and_unknown_is_never_resent(){ $c=$this->fixture();$r=$this->postJson('/admin/marketing/campaigns/'.$c['id'].'/email-test',['version'=>$c['version'],'recipient'=>'owner@example.test','landing_url'=>url('/'),'confirmed'=>true])->assertCreated();$id=$r->json('delivery.id');$s=app(\App\Services\Marketing\MarketingEmailDelivery::class);$s->run($id);$s->run($id);$this->assertDatabaseHas('marketing_email_deliveries',['id'=>$id,'state'=>'accepted']);Mail::assertSent(\App\Mail\MarketingCampaignTestMail::class,1); }
 public function test_foreign_campaign_external_url_and_unconfirmed_are_blocked(){ $c=$this->fixture();$base=['version'=>$c['version'],'recipient'=>'owner@example.test','landing_url'=>'https://elsewhere.test/','confirmed'=>true];$this->postJson('/admin/marketing/campaigns/'.$c['id'].'/email-test',$base)->assertUnprocessable();$base['landing_url']=url('/');$base['confirmed']=false;$this->postJson('/admin/marketing/campaigns/'.$c['id'].'/email-test',$base)->assertUnprocessable();$this->actingAs(User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]));$base['confirmed']=true;$this->postJson('/admin/marketing/campaigns/'.$c['id'].'/email-test',$base)->assertNotFound();Mail::assertNothingSent(); }
 public function test_unknown_transport_result_is_not_retried(){ $c=$this->fixture();$id=$this->postJson('/admin/marketing/campaigns/'.$c['id'].'/email-test',['version'=>$c['version'],'recipient'=>'owner@example.test','landing_url'=>url('/'),'confirmed'=>true])->assertCreated()->json('delivery.id');Mail::shouldReceive('to')->once()->andThrow(new \RuntimeException('Transport result unknown'));$service=app(\App\Services\Marketing\MarketingEmailDelivery::class);$service->run($id);$service->run($id);$this->assertDatabaseHas('marketing_email_deliveries',['id'=>$id,'state'=>'unknown']);}
 public function test_email_link_records_consent_aware_visitor_activity_without_post(){ $c=$this->fixture();config(['marketing.attribution_enabled'=>true]);$id=$this->postJson('/admin/marketing/campaigns/'.$c['id'].'/email-test',['version'=>$c['version'],'recipient'=>'owner@example.test','landing_url'=>url('/'),'confirmed'=>true])->json('delivery.id');$link=DB::table('marketing_email_deliveries')->where('id',$id)->value('link_id');auth()->logout();$r=$this->get('/m/r/'.$link)->assertRedirect();parse_str(parse_url($r->headers->get('Location'),PHP_URL_QUERY),$query);$this->assertArrayHasKey('jw_ref',$query,'Tracking redirect: '.$r->headers->get('Location'));$this->postJson('/marketing/tracking/consent',['accepted'=>true,'token'=>$query['jw_ref']])->assertOk()->assertJsonPath('accepted',true);$this->postJson('/marketing/tracking/page',['navigation_id'=>(string)\Illuminate\Support\Str::uuid()])->assertJsonPath('tracked',true);$this->assertDatabaseHas('marketing_analytics_events',['campaign_id'=>$c['id'],'kind'=>'arrival']);Http::assertNothingSent(); }
 public function test_campaign_draft_creation_works_without_video_execution(){ $this->fixture();$this->postJson('/admin/marketing/campaigns/channel-drafts',['version'=>0,'channel'=>'email','name'=>'Draft on shared host','document'=>[]])->assertCreated();Http::assertNothingSent();Mail::assertNothingSent(); }
}
